import React, { useEffect, useState } from 'react';
import { challengesAPI } from '../../services/api';
import type { ChallengeStart, ChallengeResult, RewardCeremony } from '../../types';
import { GameButton } from '../ui/GameButton';
import { Loading } from '../ui/Loading';

// ---------------------------------------------------------------------------
// Math Challenge (Phase 1) — the server-validated completion gate for Math
// Jungle quests. Questions are generated by the backend; answers are graded
// by the backend; XP/coins are awarded by the backend only on a pass. This
// component never asserts a result itself.
// ---------------------------------------------------------------------------

interface MathChallengeProps {
  childId: string;
  questId: string;
  questTitle: string;
  onComplete: (reward: RewardCeremony) => void;
  onExit: () => void;
}

type Phase = 'LOADING' | 'PLAYING' | 'RESULT' | 'ERROR';

export const MathChallenge: React.FC<MathChallengeProps> = ({
  childId,
  questId,
  questTitle,
  onComplete,
  onExit,
}) => {
  const [phase, setPhase] = useState<Phase>('LOADING');
  const [challenge, setChallenge] = useState<ChallengeStart | null>(null);
  const [answers, setAnswers] = useState<string[]>([]);
  const [result, setResult] = useState<ChallengeResult | null>(null);
  const [error, setError] = useState('');

  const start = async () => {
    try {
      setPhase('LOADING');
      const data = await challengesAPI.start(childId, questId);
      setChallenge(data);
      setAnswers(new Array(data.total_questions).fill(''));
      setResult(null);
      setPhase('PLAYING');
    } catch (err) {
      console.error('Failed to start challenge:', err);
      setError('Could not start the Math Challenge. Please try again.');
      setPhase('ERROR');
    }
  };

  useEffect(() => {
    start();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [childId, questId]);

  const submit = async () => {
    if (!challenge) return;
    try {
      const numericAnswers = answers.map((a) => {
        const n = parseInt(a, 10);
        return Number.isNaN(n) ? 0 : n;
      });
      const res = await challengesAPI.submit(challenge.challenge_id, numericAnswers);
      setResult(res);
      setPhase('RESULT');
    } catch (err) {
      console.error('Failed to submit challenge:', err);
      setError('Could not check your answers. Please try again.');
      setPhase('ERROR');
    }
  };

  if (phase === 'LOADING') {
    return <Loading text="Getting your Math Challenge ready..." />;
  }

  if (phase === 'ERROR') {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-red-500 to-red-700">
        <div className="text-white text-center px-4">
          <div className="text-6xl mb-4">❌</div>
          <p className="text-xl mb-6">{error}</p>
          <div className="flex gap-4 justify-center">
            <GameButton onClick={start}>Try Again</GameButton>
            <GameButton variant="warning" onClick={onExit}>Back to Hub</GameButton>
          </div>
        </div>
      </div>
    );
  }

  if (phase === 'RESULT' && result) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-green-500 to-teal-600 px-4">
        <div className="bg-white rounded-3xl p-8 max-w-lg w-full text-center shadow-2xl">
          <div className="text-7xl mb-4">{result.passed ? '🏆' : '💪'}</div>
          <h2 className="text-3xl font-game font-bold text-gray-800 mb-2">
            {result.passed ? 'Challenge Passed!' : 'Great Effort!'}
          </h2>
          <p className="text-xl text-gray-700 mb-6">
            You got <strong>{result.correct_count}</strong> out of{' '}
            <strong>{result.total_questions}</strong> right.
          </p>

          {result.passed && result.reward && (
            <div className="bg-yellow-50 border-4 border-yellow-300 rounded-2xl p-4 mb-6">
              <div className="font-bold text-lg text-gray-800">
                +{result.reward.xp_earned} XP · 🪙 +{result.reward.coins_earned} coins
              </div>
              {result.reward.new_level && (
                <div className="text-purple-700 font-bold mt-1">
                  ⭐ Level up! You are now Level {result.reward.new_level}
                </div>
              )}
            </div>
          )}

          {result.passed && result.already_completed && (
            <p className="text-gray-600 mb-6">
              You already completed this quest before — nice practice run!
            </p>
          )}

          <div className="flex gap-4">
            {!result.passed && (
              <GameButton variant="success" onClick={start} className="flex-1">
                🔁 Try Again
              </GameButton>
            )}
            {result.passed && result.reward ? (
              <GameButton variant="success" onClick={() => onComplete(result.reward!)} className="flex-1">
                🎉 Collect Rewards
              </GameButton>
            ) : (
              <GameButton onClick={onExit} className="flex-1">
                Back to Hub
              </GameButton>
            )}
          </div>
        </div>
      </div>
    );
  }

  // PLAYING
  return (
    <div className="min-h-screen bg-gradient-to-br from-green-600 via-teal-600 to-blue-700 px-4 py-8">
      <div className="max-w-2xl mx-auto">
        <div className="text-center mb-8">
          <div className="text-6xl mb-2">🧮</div>
          <h1 className="text-4xl font-game font-bold text-white text-game-shadow">
            Math Challenge
          </h1>
          <p className="text-white/90 text-lg font-semibold mt-2">
            {questTitle} — answer all {challenge?.total_questions} questions!
          </p>
        </div>

        <div className="space-y-4 mb-8">
          {challenge?.questions.map((q, i) => (
            <div
              key={i}
              className="bg-white rounded-2xl p-5 flex items-center justify-between gap-4 shadow-lg"
            >
              <div className="text-2xl font-display font-bold text-gray-800">
                {i + 1}. {q.prompt.replace('= ?', '=')}
              </div>
              <input
                type="number"
                inputMode="numeric"
                value={answers[i] ?? ''}
                onChange={(e) => {
                  const next = [...answers];
                  next[i] = e.target.value;
                  setAnswers(next);
                }}
                className="w-28 text-center text-2xl font-bold border-4 border-gray-300 rounded-xl py-2 focus:border-roblox-blue outline-none"
                placeholder="?"
              />
            </div>
          ))}
        </div>

        <div className="flex gap-4">
          <GameButton variant="warning" onClick={onExit} size="lg">
            ✕ Exit
          </GameButton>
          <GameButton variant="success" onClick={submit} size="lg" className="flex-1">
            ✅ Check My Answers
          </GameButton>
        </div>
      </div>
    </div>
  );
};
